{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Ensure basic roles are not used at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The 'roles/editor' role is a basic role that is too permissive and should be avoided at the project level."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/compute.admin\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced the overly permissive 'roles/editor' role with 'roles/compute.admin', a more specific role that still allows administration of Compute resources, following the principle of least privilege."
}
